import { isEmpty } from 'lodash-es';
import React, {
  forwardRef,
  useImperativeHandle,
  useRef,
  PropsWithChildren,
} from 'react';

import { HistogramChartLegend } from './components/legend/HistogramChartLegend.js';
import { DEFAULT_CHART_HEIGHT } from './constants/defaults.js';
import { HistogramChart as _HistogramChart } from './HistogramChart.js';
import { useHistogramChartConfig } from './hooks/useHistogramChartConfig.js';
import { HistogramConfigProvider } from './providers/HistogramConfigProvider.js';
import { HistogramDataProvider } from './providers/HistogramDataProvider.js';
import { HistogramFilteredDataProvider } from './providers/HistogramFilteredDataProvider.js';
import { StoreProvider } from './providers/StoreProvider.js';
import { Annotations } from './slots/annotations/Annotations.js';
import { Marker } from './slots/annotations/Marker.js';
import { Track } from './slots/annotations/Track.js';
import { Legend } from './slots/Legend.js';
import { Threshold } from './slots/Threshold.js';
import { Tooltip } from './slots/Tooltip.js';
import { XAxis } from './slots/XAxis.js';
import { YAxis } from './slots/YAxis.js';
import { HistogramChartRef } from './types/histogram-ref.js';
import { HistogramChartProps } from './types/histogram.js';
import { buildAndDownloadCsv } from './utils/build-and-download-csv.js';
import { normalizeConfig } from './utils/histogram-configuration.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { ChartLayout } from '../core/components/chart-layout/ChartLayout.js';
import { getChartStatesTemplates } from '../core/components/chart-states/functions/get-chart-states-template.js';
import { CATEGORICAL_LEGEND_SIZES } from '../core/components/legend/categorical/constants.js';
import { ChartSeriesActionContext } from '../core/components/series-action/ChartSeriesActionContext.js';
import { coerceSizeValue } from '../core/functions/coerceSizeValue.js';
import { EmptyStateSlot } from '../core/slots/chart-states/EmptyStateSlot.js';
import { ErrorStateSlot } from '../core/slots/chart-states/ErrorStateSlot.js';
import { ChartType } from '../core/types/chart-types.js';

export const HistogramChartRoot = forwardRef<
  HistogramChartRef,
  PropsWithChildren<HistogramChartProps>
>((props, forwardedRef) => {
  const {
    children,
    data,
    height,
    colorPalette,
    truncationMode,
    loading,
    seriesActions,
    className,
    style,
  } = props;
  const chartHeight = coerceSizeValue(height ?? DEFAULT_CHART_HEIGHT);
  const chartConfig = useHistogramChartConfig(children, {
    colorPalette,
    truncationMode,
  });
  const { emptyState, errorState } = getChartStatesTemplates(props.children);

  const containerRef = useRef<HTMLDivElement>(null);
  const rootRef = useMergeRefs<HistogramChartRef | HTMLDivElement>([
    forwardedRef,
    containerRef,
  ]);

  useImperativeHandle(forwardedRef, () => ({
    element: containerRef.current,
    getConfig: () =>
      JSON.stringify({
        type: ChartType.Histogram,
        ...normalizeConfig(chartConfig),
      }),
    downloadData: () => {
      buildAndDownloadCsv(data);
    },
  }));

  const legendOrientation = chartConfig.legend.hidden
    ? undefined
    : chartConfig.legend.position;

  return (
    <HistogramConfigProvider config={chartConfig}>
      <HistogramDataProvider data={data}>
        <ChartSeriesActionContext.Provider
          value={{
            chartSeriesActions: seriesActions,
          }}
        >
          <StoreProvider>
            <HistogramFilteredDataProvider>
              <ChartLayout
                chartHeight={chartHeight}
                resizable={chartConfig.legend.resizable}
                legendConfig={{
                  orientation: legendOrientation,
                  ratio: chartConfig.legend.ratio,
                  hidden: chartConfig.legend.hidden,
                  sizes: CATEGORICAL_LEGEND_SIZES,
                }}
                isEmpty={isEmpty(data)}
                emptyState={emptyState}
                errorState={errorState}
                showLoader={loading}
                className={className}
                style={style}
              >
                <ChartLayout.Graph>
                  <_HistogramChart ref={rootRef} />
                </ChartLayout.Graph>
                <ChartLayout.Legend>
                  {!chartConfig.legend.hidden && <HistogramChartLegend />}
                </ChartLayout.Legend>
              </ChartLayout>
            </HistogramFilteredDataProvider>
          </StoreProvider>
        </ChartSeriesActionContext.Provider>
      </HistogramDataProvider>
    </HistogramConfigProvider>
  );
});

HistogramChartRoot['displayName'] = 'HistogramChartRoot';

export const HistogramChart = Object.assign(HistogramChartRoot, {
  XAxis,
  YAxis,
  Legend,
  Tooltip,
  EmptyState: EmptyStateSlot,
  ErrorState: ErrorStateSlot,
  Annotations,
  Threshold,
});

/** Annotations Slots */
export const HistogramAnnotations = Object.assign(
  {},
  {
    Marker,
    Track,
  },
);
